import{_ as e,c as r,o as i,ae as t}from"./chunks/framework.CHDT0Kbg.js";const m=JSON.parse('{"title":"隱私權政策","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/privacy-policy.md","filePath":"zh-TW/guide/privacy-policy.md","lastUpdated":1795170900000}'),o={name:"zh-TW/guide/privacy-policy.md"};function l(c,a,h,n,s,d){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="隱私權政策" tabindex="-1">隱私權政策 <a class="header-anchor" href="#隱私權政策" aria-label="Permalink to &quot;隱私權政策&quot;">​</a></h1><p>Persim 收集什麼，什麼只留在你的裝置上。</p><h2 id="無需帳號-沒有雲端資料" tabindex="-1">無需帳號，沒有雲端資料 <a class="header-anchor" href="#無需帳號-沒有雲端資料" aria-label="Permalink to &quot;無需帳號，沒有雲端資料&quot;">​</a></h2><p>Persim 不需要登入，也不會為你建立線上帳號。歷史記錄、書籤、開啟的分頁、下載與 Cookie 都儲存在你的 Mac 上。</p><h2 id="開啟網頁時用到的資訊" tabindex="-1">開啟網頁時用到的資訊 <a class="header-anchor" href="#開啟網頁時用到的資訊" aria-label="Permalink to &quot;開啟網頁時用到的資訊&quot;">​</a></h2><p>和所有瀏覽器一樣，Persim 會把你造訪的位址傳送給對應網站。Persim 本身不會將你的瀏覽歷史上傳到伺服器。</p><h2 id="你可以開啟的網路功能" tabindex="-1">你可以開啟的網路功能 <a class="header-anchor" href="#你可以開啟的網路功能" aria-label="Permalink to &quot;你可以開啟的網路功能&quot;">​</a></h2><ul><li>廣告攔截訂閱會連線更新規則；更新失敗時，已儲存的規則繼續生效。</li><li>油猴腳本與你下載的檔案，只在你主動操作時才會取得。</li><li>在網址列輸入時會向你選擇的搜尋引擎取得搜尋建議。</li></ul><h2 id="本機權限" tabindex="-1">本機權限 <a class="header-anchor" href="#本機權限" aria-label="Permalink to &quot;本機權限&quot;">​</a></h2><p>相機、麥克風與檔案權限按網站分別記住，可在設定裡修改。定位與通知由 macOS 管理。無痕視窗（⌘⇧N）不會寫入歷史記錄或工作階段。</p><h2 id="協力廠商網站" tabindex="-1">協力廠商網站 <a class="header-anchor" href="#協力廠商網站" aria-label="Permalink to &quot;協力廠商網站&quot;">​</a></h2><p>你造訪的網站由他人經營，遵循各自的隱私權政策。Persim 的內建頁面不會追蹤你。</p><h2 id="聯絡我們" tabindex="-1">聯絡我們 <a class="header-anchor" href="#聯絡我們" aria-label="Permalink to &quot;聯絡我們&quot;">​</a></h2><p>隱私相關問題：<strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>。</p>',14)])])}const u=e(o,[["render",l]]);export{m as __pageData,u as default};
